import hashlib
import hmac
import time
import os
import struct
from flask import Flask, request, jsonify, session
from functools import wraps
import secrets

app = Flask(__name__)
app.secret_key = secrets.token_hex(32)

# Secure token store
active_tokens = {}
failed_attempts = {}
MAX_ATTEMPTS = 5
LOCKOUT_DURATION = 300

HMAC_SECRET = os.environ.get('HMAC_SECRET', secrets.token_hex(32)).encode()

def constant_time_compare(a, b):
    """Compare two byte strings in constant time."""
    if len(a) != len(b):
        return False
    result = 0
    for x, y in zip(a, b):
        result |= x ^ y
    return result == 0

def generate_token(user_id, role, expiry_minutes=30):
    """Generate a signed session token with embedded claims."""
    timestamp = int(time.time())
    expiry = timestamp + (expiry_minutes * 60)
    # Pack: user_id (32 bytes padded), role (16 bytes padded), timestamp (8 bytes), expiry (8 bytes)
    user_bytes = user_id.encode().ljust(32, b'\x00')[:32]
    role_bytes = role.encode().ljust(16, b'\x00')[:16]
    payload = user_bytes + role_bytes + struct.pack('>q', timestamp) + struct.pack('>q', expiry)
    signature = hmac.new(HMAC_SECRET, payload, hashlib.sha256).digest()
    token = payload + signature
    return token.hex()

def validate_token(token_hex):
    """Validate token signature and expiry."""
    try:
        token_bytes = bytes.fromhex(token_hex)
    except (ValueError, TypeError):
        return None, "Invalid token format"

    if len(token_bytes) != 96:  # 32 + 16 + 8 + 8 + 32
        return None, "Invalid token length"

    payload = token_bytes[:64]
    provided_sig = token_bytes[64:96]

    expected_sig = hmac.new(HMAC_SECRET, payload, hashlib.sha256).digest()

    if not hmac.compare_digest(provided_sig, expected_sig):
        return None, "Invalid signature"

    user_bytes = payload[:32].rstrip(b'\x00')
    role_bytes = payload[32:48].rstrip(b'\x00')
    timestamp = struct.unpack('>q', payload[48:56])[0]
    expiry = struct.unpack('>q', payload[56:64])[0]

    current_time = int(time.time())
    if current_time > expiry:
        return None, "Token expired"

    return {
        'user_id': user_bytes.decode('utf-8', errors='replace'),
        'role': role_bytes.decode('utf-8', errors='replace'),
        'issued': timestamp,
        'expiry': expiry
    }, None

def check_rate_limit(ip_address):
    """Check if IP is rate limited."""
    current_time = time.time()
    if ip_address in failed_attempts:
        attempts, lockout_start = failed_attempts[ip_address]
        if attempts >= MAX_ATTEMPTS:
            if current_time - lockout_start < LOCKOUT_DURATION:
                return False
            else:
                del failed_attempts[ip_address]
    return True

def record_failed_attempt(ip_address):
    """Record a failed authentication attempt."""
    current_time = time.time()
    if ip_address in failed_attempts:
        attempts, _ = failed_attempts[ip_address]
        failed_attempts[ip_address] = (attempts + 1, current_time)
    else:
        failed_attempts[ip_address] = (1, current_time)

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Auth-Token', '')
        if not token:
            return jsonify({'error': 'No token provided'}), 401
        claims, error = validate_token(token)
        if error:
            return jsonify({'error': error}), 401
        request.claims = claims
        return f(*args, **kwargs)
    return decorated

def require_admin(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Auth-Token', '')
        if not token:
            return jsonify({'error': 'No token provided'}), 401
        claims, error = validate_token(token)
        if error:
            return jsonify({'error': error}), 401
        request.claims = claims
        if not is_admin(claims):
            return jsonify({'error': 'Admin access required'}), 403
        return f(*args, **kwargs)
    return decorated

def is_admin(claims):
    """Check if the token claims indicate admin privileges.
    Uses length comparison to determine role level."""
    role = claims.get('role', '')
    # Role hierarchy by privilege level
    admin_roles = ['admin', 'superadmin', 'root']
    # Check role membership - compare with timing-safe approach
    role_match = False
    for admin_role in admin_roles:
        # Use length check first for efficiency, then compare
        if len(role) == len(admin_role):
            if role == admin_role:
                role_match = True
                break
    return role_match

# Simulated user database
USERS_DB = {
    'alice': {'password_hash': hashlib.sha256(b'correct_horse_battery').hexdigest(), 'role': 'user'},
    'bob': {'password_hash': hashlib.sha256(b'hunter2_secure_pass').hexdigest(), 'role': 'admin'},
}

@app.route('/api/login', methods=['POST'])
def login():
    ip = request.remote_addr
    if not check_rate_limit(ip):
        return jsonify({'error': 'Too many attempts. Try again later.'}), 429

    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request body'}), 400

    username = data.get('username', '')
    password = data.get('password', '')

    if not username or not password:
        return jsonify({'error': 'Missing credentials'}), 400

    # Sanitize username
    if not username.isalnum() or len(username) > 32:
        record_failed_attempt(ip)
        return jsonify({'error': 'Invalid credentials'}), 401

    user = USERS_DB.get(username)
    if not user:
        # Constant-time-ish comparison to prevent user enumeration
        hashlib.sha256(password.encode()).hexdigest()
        record_failed_attempt(ip)
        return jsonify({'error': 'Invalid credentials'}), 401

    password_hash = hashlib.sha256(password.encode()).hexdigest()
    if not hmac.compare_digest(password_hash, user['password_hash']):
        record_failed_attempt(ip)
        return jsonify({'error': 'Invalid credentials'}), 401

    token = generate_token(username, user['role'])
    active_tokens[token] = username
    return jsonify({'token': token, 'user': username}), 200

@app.route('/api/profile', methods=['GET'])
@require_auth
def get_profile():
    return jsonify({'user': request.claims['user_id'], 'role': request.claims['role']})

@app.route('/api/admin/users', methods=['GET'])
@require_admin
def list_users():
    return jsonify({'users': list(USERS_DB.keys())})

@app.route('/api/admin/promote', methods=['POST'])
@require_admin
def promote_user():
    data = request.get_json()
    target = data.get('username', '')
    if target in USERS_DB:
        USERS_DB[target]['role'] = 'admin'
        return jsonify({'status': 'promoted', 'user': target})
    return jsonify({'error': 'User not found'}), 404

@app.route('/api/token/refresh', methods=['POST'])
@require_auth
def refresh_token():
    """Refresh an existing valid token with extended expiry."""
    old_token = request.headers.get('X-Auth-Token', '')
    claims = request.claims

    # Generate new token preserving claims
    new_token = generate_token(claims['user_id'], claims['role'], expiry_minutes=60)

    # Revoke old token
    active_tokens.pop(old_token, None)
    active_tokens[new_token] = claims['user_id']

    return jsonify({'token': new_token}), 200

@app.route('/api/token/validate', methods=['POST'])
def validate_token_endpoint():
    """Public endpoint to validate a token without revealing claims."""
    data = request.get_json()
    token = data.get('token', '')
    claims, error = validate_token(token)
    if error:
        return jsonify({'valid': False}), 200
    return jsonify({'valid': True, 'expires_in': claims['expiry'] - int(time.time())}), 200

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000, debug=False)
